PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, canonical TEXT UNIQUE NOT NULL, fingerprint TEXT NOT NULL, payload TEXT NOT NULL, content_hash TEXT NOT NULL, discovered TEXT NOT NULL, updated TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new');
CREATE INDEX IF NOT EXISTS job_fingerprint ON jobs(fingerprint);
CREATE TABLE IF NOT EXISTS documents(job_id TEXT PRIMARY KEY REFERENCES jobs(id), cache_key TEXT NOT NULL, payload TEXT NOT NULL, reviewed INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), snapshot_hash TEXT NOT NULL, snapshot TEXT NOT NULL, created TEXT NOT NULL, expires TEXT NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS receipts(job_id TEXT PRIMARY KEY REFERENCES jobs(id), evidence TEXT NOT NULL, applied_at TEXT NOT NULL, verification TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, event TEXT NOT NULL, job_id TEXT, details TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage(id INTEGER PRIMARY KEY, day TEXT NOT NULL, reserved REAL NOT NULL, estimated REAL, state TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feeds(key TEXT PRIMARY KEY, etag TEXT, modified TEXT, payload TEXT, next_fetch REAL NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS alerts(job_id TEXT PRIMARY KEY REFERENCES jobs(id), state TEXT NOT NULL, created TEXT NOT NULL);
